const { sortByTransactionId, sortByNoticeId } = require("../utils/sort");

const STATUS_ORDER = { pending: 0, approved: 1, rejected: 2, reversed: 3 };

function cmpStatus(a, b) {
  const aa = STATUS_ORDER[String(a || "").toLowerCase()] ?? -1;
  const bb = STATUS_ORDER[String(b || "").toLowerCase()] ?? -1;
  return aa - bb;
}

function normStatus(s) {
  const v = String(s || "").toLowerCase();
  return Object.hasOwn(STATUS_ORDER, v) ? v : "pending";
}

function round2(n) {
  return Math.round((Number(n) + Number.EPSILON) * 100) / 100;
}

function pickWinningCorrections(corrections) {
  // Winner per (transaction_id, field): lexicographically greatest effective date.
  // If effective ties, pick lexicographically greatest notice_id for determinism.
  const winners = new Map();
  for (const c of corrections) {
    if (!c || !c.transaction_id || !c.field || !c.notice_id || !c.effective) continue;
    const key = `${c.transaction_id}::${c.field}`;
    const prev = winners.get(key);
    if (!prev) {
      winners.set(key, c);
      continue;
    }
    if (String(c.effective) > String(prev.effective)) {
      winners.set(key, c);
    } else if (String(c.effective) === String(prev.effective) && String(c.notice_id) > String(prev.notice_id)) {
      winners.set(key, c);
    }
  }
  return [...winners.values()];
}

function reconcileTransactions(parsed) {
  const byId = new Map();
  for (const row of parsed.ledger) {
    byId.set(row.transaction_id, { ...row, status: normStatus(row.status) });
  }

  // Meeting amendments (Brief 05)
  for (const meeting of parsed.meetings) {
    const target = byId.get(meeting.transaction_id);
    if (!target) continue;
    if (!meeting.signed) continue;
    if (meeting.effective) {
      if (String(meeting.effective) < String(target.date)) continue;
    }
    if (meeting.owner) target.owner = meeting.owner;
  }

  // Emails (Brief 02 + 03)
  for (const email of parsed.emails) {
    const target = byId.get(email.transaction_id);
    if (!target) continue;
    if (!String(email.from_addr || "").includes("compliance@")) continue;

    const candidate = normStatus(email.status);

    // If sent date present, only apply if sent >= ledger date
    // (ledger date; note Brief 09 only affects compliance_hold timing)
    if (email.sent && String(email.sent) < String(target.date)) {
      continue;
    }

    // Apply only if precedence allows (never downgrade)
    if (cmpStatus(candidate, target.status) >= 0) {
      target.status = candidate;
    }
  }

  // Snapshot date for compliance_hold comparison per Brief 09:
  // date after ledger load + meeting amendments + emails, but before corrections.
  const preCorrectionDateById = new Map();
  for (const [id, row] of byId.entries()) {
    preCorrectionDateById.set(id, row.date);
  }

  // Corrections (Brief 04): pick winners per (txn, field)
  const winning = pickWinningCorrections(parsed.corrections);
  // Apply in a deterministic order: effective asc, then notice_id asc.
  // (previous_value is defined immediately before each notice applies; this order
  // is stable and ensures deterministic application when multiple fields.)
  winning.sort((a, b) => {
    if (a.effective === b.effective) {
      return a.notice_id < b.notice_id ? -1 : a.notice_id > b.notice_id ? 1 : 0;
    }
    return a.effective < b.effective ? -1 : 1;
  });

  const report = [];
  // Track whether a winning correction changed status/date (for Brief 06/08)
  const winningStatusChanged = new Set();
  const winningDateChanged = new Set();

  for (const notice of winning) {
    const target = byId.get(notice.transaction_id);
    if (!target) continue;

    let field = notice.field;
    if (field === "date") field = "date";
    if (field === "status") field = "status";
    if (field === "owner") field = "owner";

    const prevVal = target[field] == null ? "" : String(target[field]);

    if (field === "owner") {
      target.owner = notice.value;
    } else if (field === "status") {
      target.status = normStatus(notice.value);
      winningStatusChanged.add(notice.transaction_id);
    } else if (field === "date") {
      target.date = notice.value;
      winningDateChanged.add(notice.transaction_id);
    }

    report.push({
      notice_id: notice.notice_id,
      transaction_id: notice.transaction_id,
      field: notice.field,
      previous_value: prevVal,
      new_value: String(notice.value),
      effective: notice.effective,
    });
  }

  // Sort report by notice_id asc per contract (writer also sorts)
  sortByNoticeId(report);

  // Build final items and compute effective_date (Brief 06)
  const items = [];
  for (const row of byId.values()) {
    const txnId = row.transaction_id;
    // Default effective_date from ledger/date after corrections unless overridden
    let effective_date = row.date;

    // If a winning correction modified status or date, set effective_date to that
    // notice's effective date (lexicographically greatest effective among those winners)
    // (Brief 06)
    let corrEffective = null;
    for (const r of report) {
      if (r.transaction_id !== txnId) continue;
      if (r.field === "status" || r.field === "date") {
        if (corrEffective == null || String(r.effective) > String(corrEffective)) {
          corrEffective = r.effective;
        }
      }
    }
    if (corrEffective) effective_date = corrEffective;

    items.push({
      transaction_id: txnId,
      owner: row.owner,
      status: normStatus(row.status),
      effective_date,
      amount_usd: round2(row.amount),
      exception_reason: null,

      // internal helpers (stripped later)
      __preCorrectionLedgerDate: preCorrectionDateById.get(txnId),
      __hasWinningStatusCorrection: winningStatusChanged.has(txnId),
    });
  }

  // Exception flags (Brief 07/08)
  for (const item of items) {
    const codes = [];
    if (item.amount_usd > 10000) codes.push("over_limit");

    // compliance_hold (Brief 07 + Brief 09)
    if (item.status === "rejected") {
      const qualifying = parsed.emails.some((e) => {
        if (e.transaction_id !== item.transaction_id) return false;
        if (!String(e.from_addr || "").includes("compliance@")) return false;
        if (!e.sent) return false;
        // compare against ledger date immediately before corrections are applied
        return String(e.sent) >= String(item.__preCorrectionLedgerDate);
      });
      if (qualifying) codes.push("compliance_hold");
    }

    // policy_waiver (Brief 08)
    if (item.status === "approved" && parsed.policyExceptions && parsed.policyExceptions.has(item.transaction_id)) {
      codes.push("policy_waiver");
    }

    // post_reversal_review (Brief 08)
    if (item.status === "reversed" && item.amount_usd > 5000 && item.__hasWinningStatusCorrection) {
      codes.push("post_reversal_review");
    }

    codes.sort();
    item.exception_reason = codes.length ? codes.join(";") : null;

    delete item.__preCorrectionLedgerDate;
    delete item.__hasWinningStatusCorrection;
  }

  sortByTransactionId(items);

  return { items, report };
}

module.exports = { reconcileTransactions, STATUS_ORDER };
